INSERT INTO `mangas` (`id`, `manga_id`, `title`, `description`, `cover_image_url`, `latest_chapter_number`, `created_at`, `updated_at`, `alternative_title`, `author`, `artist`, `genres`, `release_year`, `rating`, `last_read_chapter_id`, `last_read_chapter_number`, `last_read_at`) VALUES
(1, 'd3b05787-4c8e-42bb-ba9a-6b2fafd92f3c', 'Nano Machine', 'Setelah direndahkan dan menghabiskan hidupnya dalam bahaya seorang yatim piatu dari pemuja iblis YeoWoon mendapatkan kunjungan tak terduga dari keturunannya dari masa depan yang memasukkan sebuah mesin nano ke dalam tubuh CheonWoon yang mengubah hidup Cheon Yeo Woon setelah aktivasi Ikuti Cerita tentang perjalanan Cheon YeoWoon di reaperscansid melewati pemujaan setan dan naik menjadi yang ahli beladiri terbaik baru saja dimulai', 'https://assets.shngm.id/thumbnail/image/38e34bb8-29c2-43f6-a2cc-ec9d4991ff5a.jpg', 322, '2026-07-29 09:34:31', '2026-07-29 10:18:36', '나노마신', 'Han-Joong-Wueol-Ya', 'Redice Studio, Guem-Gang-Bul-Gae', 'Action, Adventure, Fantasy', '2020', 9.4, NULL, NULL, NULL),
(2, '07cba925-da21-497e-a5e0-b2ca712917df', 'The Rebel Of The Tyrant Noble Family', 'Ash mengabdikan seluruh hidupnya kepada ayah angkatnya, bertekad membalas budi karena telah diterima dan dibesarkan sebagai seorang yatim piatu.\n\nNamun, kebenaran yang ia ketahui tepat di ambang kematian ternyata sama sekali berbeda.\n\nSemua usaha yang telah ia bangun…\n\nSemua kepercayaan yang telah ia berikan…\n\nBahkan kekuatan terhebat yang sejak awal terlahir bersamanya —Seven Wings—\n\nSemuanya telah dirampas darinya…!\n\nKalau begitu…\n\nAkankah kita memulai kehidupan pembalasan dan pembalikan takdir?', 'https://assets.shngm.id/thumbnail/cover/banner_1779114042625_r6y8oj.jpg', 33, '2026-07-29 09:44:28', '2026-07-29 09:44:28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
